"""Original PL-300 answer labels and explanatory definitions."""
TERMS = {}


def t(key, label, meaning):
    if key in TERMS:
        raise ValueError(f'Duplicate term: {key}')
    TERMS[key] = (label, meaning)


# --- Domain 1: connect, profile, clean, shape, combine, load ---------------
t('importmode', 'Import mode', 'Import copies the data into the semantic model at refresh, which gives the fastest queries and the most DAX flexibility but stores the data twice and needs a refresh schedule.')
t('directquery', 'DirectQuery', 'DirectQuery sends queries to the source at report time, so the report never shows stale data but the source bears the query load and some DAX is restricted.')
t('directlake', 'DirectLake over a lakehouse', 'DirectLake reads Delta tables directly, which gives Import-like speed without a copy, but it requires Fabric capacity and supported Delta tables.')
t('dualmode', 'Dual mode table', 'A Dual table can act as Import for some relationships and DirectQuery for others, which reduces the number of DirectQuery round trips in a composite model.')
t('liveconn', 'Live connection to a published semantic model', 'A live connection reuses a governed semantic model without copying it, so consistency and security are inherited and the report is not edited in Desktop.')
t('sharedmodel', 'Connect to a shared semantic model instead of importing the source again', 'Reusing the certified model keeps one definition of the metric and inherits its refresh and row-level security.')
t('params', 'Create a parameter for the server, path, or filter', 'A parameter lets one query point at different environments without editing the M code, which makes promotion between dev, test, and prod safe.')
t('creds', 'Update the data source credentials in the semantic model settings', 'Credentials live with the data source connection in the service, so a changed password must be updated there or refresh fails.')
t('privacy', 'Set privacy levels to isolate the sources', 'Privacy levels stop the engine from folding data across sources it should not combine, which prevents accidental exposure of confidential values.')
t('datasourcechange', 'Change the data source settings rather than rebuilding the query', 'Editing the connection keeps the applied steps and lets you repoint an existing query at a new location.')
t('profiling', 'Profile the column with column quality, distribution, and profile views', 'Profiling shows how many values are valid, distinct, and empty before any transformation is chosen.')
t('columnstats', 'Review column statistics and value distribution', 'Value distribution reveals skew, unexpected dominant values, and long tails that a simple row count hides.')
t('columntype', 'Correct the column data type before building the model', 'A wrong data type blocks time intelligence, breaks relationships, and inflates the model through text storage of numbers and dates.')
t('nullreplace', 'Replace nulls with a defined placeholder or a filled-down value', 'Replacing nulls makes aggregations reproducible; the placeholder must be documented so it is not mistaken for a measurement.')
t('errorremove', 'Filter out the error rows and report them separately', 'Removing errors keeps the model loadable, but the discarded rows must be reported so the business knows what is missing.')
t('importederror', 'Trace the import error to the source type mismatch', 'Most import errors come from a value that does not match the declared type, so the fix is at the source column or an explicit conversion.')
t('duplicatecheck', 'Remove duplicate rows using the natural business key', 'De-duplicating on the business key prevents double counting when a source system repeats records across loads.')
t('trimclean', 'Trim, clean, and standardize the text values', 'Leading spaces, inconsistent casing, and stray characters create duplicate dimension members and break joins.')
t('datatypecast', 'Use a locale-aware conversion for dates and decimals', 'A locale-aware conversion stops day and month being swapped and stops decimal commas being interpreted as text.')
t('customcolumn', 'Add a custom column with an M expression', 'A custom column derives a new value row by row, which suits logic that built-in transformations cannot express.')
t('conditionalcolumn', 'Add a conditional column for rule-based bucketing', 'A conditional column applies explicit if-then rules, which is easier to review than a hand-written expression.')
t('groupby', 'Group by the key and aggregate the measures', 'Grouping reduces a transactional table to one row per key, which is the usual shape for a summary or a dimension.')
t('aggregate', 'Add an aggregate step with the correct summarization', 'The summarization choice decides whether the result is a sum, count, or distinct count, and a wrong one silently changes the number.')
t('splitcol', 'Split the combined column into separate fields', 'Splitting separates values that are packed into one field so each can be typed, filtered, and related correctly.')
t('extractedtext', 'Extract the needed part of the text with a delimiter or position', 'Extraction keeps the useful part of an identifier without importing the whole string into the model.')
t('replacedvalue', 'Replace the specific values that are wrong', 'Targeted replacement fixes known bad codes without disturbing values that are already correct.')
t('pivotcol', 'Pivot the attribute values into columns', 'Pivoting turns row-based attribute values into columns, which suits a cross-tab source that must become a flat table.')
t('unpivotcol', 'Unpivot the month columns into rows', 'Unpivoting turns wide period columns into a single date column and a single value column, which is what a tabular model needs.')
t('transpose', 'Transpose the table so the header becomes a column', 'Transposing swaps rows and columns, which repairs a report-shaped sheet whose headings run down the side.')
t('jsonrecord', 'Expand the JSON record into typed columns', 'Expanding a JSON record exposes its fields as columns that can be typed, filtered, and related.')
t('xmltable', 'Convert the XML or JSON list into a table of rows', 'A nested list must become rows before it can be modelled, because a model cannot aggregate a cell that holds a list.')
t('listtotable', 'Convert the list value to a table and expand it', 'Converting a list to a table preserves every element as a row instead of keeping only the first value.')
t('mergejoin', 'Merge the two queries on a matching key', 'A merge joins columns from two queries side by side using a key, which is how a lookup is added to a fact query.')
t('appendq', 'Append the queries into one table', 'Appending stacks rows with the same shape, which combines monthly extracts or regions into one table.')
t('leftouter', 'Use a left outer join to keep every fact row', 'A left outer join keeps unmatched fact rows with null lookups, which exposes missing dimension members instead of silently dropping sales.')
t('fuzzymerge', 'Use a fuzzy merge with a similarity threshold', 'A fuzzy merge matches near-spellings when keys differ, but the matches must be reviewed because a threshold can join the wrong records.')
t('keycolumn', 'Create an integer surrogate key for the relationship', 'A single integer key is compact, stable, and avoids relationships built on text or composite columns.')
t('referenceq', 'Reference the query so later steps can diverge', 'A reference reuses the earlier steps of a query while allowing a different downstream shape, which avoids loading the base table twice.')
t('duplicateq', 'Duplicate the query so the two are independent', 'A duplicate copies the full step chain, so a change in one copy does not affect the other but the work is repeated.')
t('folding', 'Keep the steps foldable so the source does the work', 'Query folding pushes transformations back to the source, which is faster and lets incremental refresh work.')
t('nativequery', 'Use a native query to select only the needed rows', 'A native query reduces what is transferred, but it can break folding for later steps and must be maintained as the schema changes.')
t('stagingq', 'Stage the raw query and build a separate clean query on it', 'Staging separates extraction from transformation, which makes each layer easier to test and reuse.')
t('factload', 'Load the transactional query as a fact table', 'The fact table holds the keys and additive measures at the grain of the event, which is what the model aggregates.')
t('dimload', 'Load the distinct attribute query as a dimension table', 'The dimension holds one row per member with descriptive attributes, which is what slicers and labels use.')
t('loaddisable', 'Disable load on the staging query', 'Disabling load keeps a working query out of the model, which prevents unused tables from inflating the dataset.')
t('dataflowq', 'Reuse a dataflow for the shared transformation', 'A dataflow centralizes preparation so several models consume one governed set of cleaned tables.')
t('lakehousedest', 'Land the prepared table in a lakehouse and model it downstream', 'Landing in a lakehouse separates preparation from modelling and lets several semantic models read the same curated table.')

# --- Domain 2: schema, relationships, dates, DAX, performance -------------
t('starschema', 'Build a star schema with a fact table and conformed dimensions', 'A star schema puts measurable events in one fact table surrounded by descriptive dimensions, which is the shape the engine and DAX are optimized for.')
t('snowflake', 'Normalize the dimension into a snowflake', 'Snowflaking splits a dimension into related tables, which reduces duplication but adds hops and slows filters.')
t('flattendim', 'Flatten the lookup attributes into a single dimension', 'Flattening keeps one hop between fact and filter, which is simpler for report authors and faster for the engine.')
t('tableprops', 'Set the table and column properties, including hidden keys and format strings', 'Properties control how a field behaves in the report: hidden keys disappear from the field list and format strings fix how values display.')
t('hiddencols', 'Hide technical columns from the report view', 'Hiding keys and helper columns stops report authors using an ID as a label and keeps the field list readable.')
t('one2many', 'One-to-many relationship from the dimension to the fact', 'A one-to-many relationship from the unique dimension key to the repeated fact key is the standard star relationship.')
t('many2many', 'Many-to-many relationship with a bridging table', 'Many-to-many is needed when neither side is unique, and a bridge table keeps the filter path explicit rather than ambiguous.')
t('one2one', 'One-to-one relationship between two tables with the same grain', 'One-to-one suits two tables that describe the same entity, and it is usually a sign the tables could be merged.')
t('singlefilter', 'Single-direction filter from dimension to fact', 'Single direction keeps filter flow predictable and avoids ambiguous paths that the engine has to resolve.')
t('bothfilter', 'Bi-directional cross-filtering on the relationship', 'Bi-directional filtering lets a fact filter a dimension, which is occasionally required but can create ambiguity and slow queries.')
t('inactive', 'Inactive relationship activated with USERELATIONSHIP', 'An inactive relationship exists but does not filter until a measure activates it, which is how one fact supports several dates.')
t('userel', 'Activate the relationship inside the measure with USERELATIONSHIP', 'USERELATIONSHIP switches the relationship used by a single measure, so order date and ship date can both be analysed without a second fact table.')
t('crossfilter', 'Set the cross-filter direction on the relationship', 'Cross-filter direction decides which table filters which, and changing it is the usual fix for a filter that does not reach the visual.')
t('datetable', 'Create a dedicated date table marked as the date table', 'A marked date table with contiguous dates is what time intelligence functions require and what slicers should use.')
t('markeddate', 'Mark the table as a date table', 'Marking the date table tells the engine which table supplies the date hierarchy, which removes ambiguity when several date columns exist.')
t('roleplaying', 'Create one date table and role-play it through several relationships', 'Role-playing reuses a single date dimension for order, ship, and due dates, which avoids three near-identical date tables.')
t('fiscalcalendar', 'Build the fiscal periods as columns in the date table', 'Fiscal columns let time intelligence follow the organization\'s year instead of the calendar year.')
t('datehierarchy', 'Add a year-quarter-month hierarchy for drill-down', 'A hierarchy gives report authors a consistent drill path instead of ad hoc field combinations.')
t('measure', 'Create a measure for the aggregation', 'A measure is evaluated in the filter context of the visual, so it responds to slicers automatically and does not inflate the model.')
t('calcColumn', 'Create a calculated column', 'A calculated column is computed row by row at refresh and stored, which suits a value needed for slicing or a relationship.')
t('calcTable', 'Create a calculated table', 'A calculated table materializes at refresh, which suits a small derived table such as a parameter or a bridge.')
t('filtercontext', 'The filter context supplied by the visual, slicers, and page filters', 'Filter context is what the visual and its slicers impose on a measure at evaluation time, and it explains most unexpected totals.')
t('rowcontext', 'The row context inside an iterator', 'Row context exists inside a calculated column or an iterator function and is the reason RELATED is needed to reach another table.')
t('divide', 'Use DIVIDE instead of the division operator', 'DIVIDE returns blank instead of an error when the denominator is zero, which keeps ratio visuals clean.')
t('sumx', 'Use an iterator such as SUMX over the row-level expression', 'An iterator evaluates the expression per row and then aggregates, which is required when the value to sum is not a stored column.')
t('distinctcount', 'Use DISTINCT COUNT for unique entities', 'Distinct count answers how many unique customers or orders, which a plain count would overstate.')
t('iterator', 'Use an iterator function for row-level arithmetic', 'Iterators such as SUMX and AVERAGEX apply a calculation per row, which is the difference between an average of ratios and a ratio of totals.')
t('calculate', 'Wrap the aggregation in CALCULATE to change the filter context', 'CALCULATE evaluates an expression under modified filters, which is how ratios, shares, and prior-period values are built.')
t('keepfilters', 'Add KEEPFILTERS to intersect rather than replace the filter', 'KEEPFILTERS keeps the existing filter and intersects it with the new one, which prevents a measure from reporting values outside the current selection.')
t('removefilters', 'Remove the filter with REMOVEFILTERS or ALL', 'Removing a filter lets a measure compute a total or share regardless of the current slicer selection.')
t('allselected', 'Use ALLSELECTED to respect the slicer but ignore the visual', 'ALLSELECTED computes a share within the user\'s chosen selection rather than the whole table, which is usually what a percent-of-total wants.')
t('allfunc', 'Use ALL on the table to clear its filters', 'ALL clears filters from a table, which is the basis for share-of-total and denominator calculations.')
t('variables', 'Store intermediate results in VAR and RETURN', 'Variables compute once, make a measure readable, and prevent a filter modifier from being applied differently in two places.')
t('ytd', 'Use TOTALYTD or DATESYTD for year-to-date', 'Year-to-date functions accumulate from the start of the year defined by the marked date table.')
t('samperiodly', 'Use SAMEPERIODLASTYEAR or DATEADD for the comparable period', 'The comparable-period functions shift the current selection back a year, which is how year-over-year is computed correctly.')
t('movingavg', 'Use AVERAGEX over a rolling date window', 'A rolling window averages a trailing number of periods, which smooths a noisy series without hiding the current value.')
t('semiadditive', 'Use LASTNONBLANK or LASTDATE for a semi-additive balance', 'Balances such as inventory should not be summed across time, so the measure takes the value at the last date in the period.')
t('lastnonblank', 'Use LASTNONBLANK when the balance is only recorded on some dates', 'LASTNONBLANK finds the most recent date that actually has a value, which handles accounts that are not updated daily.')
t('datesinperiod', 'Use DATESINPERIOD for a windowed calculation', 'DATESINPERIOD returns a range ending at the current date, which is the basis for rolling totals.')
t('timeintel', 'Build the measure against the marked date table', 'Time intelligence only works reliably when the date table is contiguous and marked, so the measure must reference it rather than a fact date column.')
t('quickmeasure', 'Use a quick measure for the standard pattern', 'A quick measure generates the DAX for a common pattern such as a running total, which is faster and less error-prone than hand-writing it.')
t('calculationgroup', 'Create a calculation group for the time-intelligence variants', 'A calculation group applies the same set of variants to every measure, which replaces dozens of near-identical measures.')
t('fieldparam', 'Create a field parameter so the author can switch the measure or axis', 'A field parameter lets one visual switch between measures or dimensions without duplicating pages.')
t('whatif', 'Create a numeric range parameter for scenario analysis', 'A what-if parameter feeds a measure that applies the selected value, which lets users test assumptions in the report.')
t('percentile', 'Use PERCENTILE.INC for a distribution boundary', 'A percentile returns the value below which a share of observations fall, which describes a distribution rather than an average.')
t('correlation', 'Use a statistical function such as STDEV.P or MEDIAN to describe the spread', 'Descriptive statistics show the shape of the data, which an average alone hides.')
t('perfanalyzer', 'Run Performance Analyzer to find the slow visual', 'Performance Analyzer times each visual and separates DAX, query, and rendering cost, which identifies where the delay actually is.')
t('daxqueryview', 'Inspect the query plan in DAX query view', 'DAX query view shows the generated query and its timings, which is how a slow measure is isolated from a slow visual.')
t('vertipaq', 'Reduce column cardinality and width to shrink the VertiPaq store', 'The in-memory store compresses repeated and narrow values well, so trimming high-cardinality text and unused columns is the main size lever.')
t('cardinalitytrim', 'Remove the high-cardinality columns the report does not use', 'A column with almost unique values compresses badly and can dominate model size for no analytical benefit.')
t('aggregation', 'Add an aggregation table for the large fact', 'A pre-aggregated table answers common summaries quickly while the detail stays available for drillthrough.')
t('reducegran', 'Reduce the granularity loaded into the model', 'Loading to the grain the report actually needs removes rows the visuals never use.')
t('modelSize', 'Remove unnecessary rows and columns before optimizing measures', 'Size work starts with what is loaded, because no DAX rewrite compensates for a model that stores data it never queries.')

# --- Domain 3: visuals, interaction, navigation, analytics, AI ------------
t('barcol', 'A clustered bar or column chart', 'Bar and column charts compare a measure across categories, which is the right default for ranking or comparison.')
t('linechart', 'A line chart with a date axis', 'A line chart shows a trend over a continuous axis, which is what time series need.')
t('piechart', 'A pie or donut chart', 'A pie chart shows part-to-whole for a few categories; beyond about five slices the comparison becomes unreadable.')
t('treemap', 'A treemap', 'A treemap shows hierarchical part-to-whole through area, which suits many categories when exact comparison is secondary.')
t('waterfall', 'A waterfall chart', 'A waterfall explains how a starting value moves to an ending value through additions and subtractions.')
t('funnel', 'A funnel chart', 'A funnel shows sequential stage attrition, which suits a sales or process pipeline.')
t('scatter', 'A scatter chart', 'A scatter plot shows the relationship between two numeric measures and reveals clusters and outliers.')
t('kpi', 'A KPI visual with a target', 'A KPI visual states progress against a defined target, which a plain card cannot show.')
t('matrixv', 'A matrix visual with row and column groups', 'A matrix supports nested rows and columns with subtotals, which is the report equivalent of a pivot table.')
t('gauge', 'A gauge visual', 'A gauge shows one value against a target range, which is compact but wastes space relative to a KPI or card.')
t('themejson', 'Apply a report theme JSON', 'A theme applies a consistent palette and formatting across every visual, which is faster and more consistent than styling each visual.')
t('condformat', 'Apply conditional formatting driven by a measure', 'Conditional formatting encodes a value as colour or an icon, which lets a reader scan exceptions instead of reading every number.')
t('selectionpane', 'Use the Selection pane to group and layer visuals', 'The Selection pane controls visibility and z-order, which is how a report builds layered or swapped views.')
t('datalabels', 'Turn on and format data labels', 'Data labels put the value next to the mark, which removes the need to read an axis for a small number of categories.')
t('axisformat', 'Set the axis range and units explicitly', 'A fixed axis prevents a small change from looking dramatic, which is an integrity issue rather than a cosmetic one.')
t('slicer', 'A slicer on the report page', 'A slicer gives the reader an obvious control over the filter, which is clearer than expecting them to use the filter pane.')
t('syncslicer', 'Sync the slicer across the pages that share the same filter', 'Syncing keeps a selection consistent as the reader moves between pages, which prevents contradictory views.')
t('interactions', 'Edit the interactions so the visual does not filter the others', 'Interaction settings decide whether a selection filters, highlights, or does nothing, which is how an executive summary stays stable.')
t('drilldown', 'Enable drill-down through the hierarchy', 'Drill-down moves from a summary level to the next level within the same visual, which keeps the context visible.')
t('drillthrough', 'Configure a drillthrough page with the entity filter', 'Drillthrough opens a detail page filtered to the selected entity, which is how a reader moves from a summary to the underlying rows.')
t('filterpane', 'Set the filter pane scope by page, report, or visual', 'Filter scope decides who the filter affects, and putting it at the wrong level is a common cause of a filter that seems to be ignored.')
t('bookmark', 'Capture the view in a bookmark', 'A bookmark stores the current filter, slicer, and visibility state, which is how a report offers saved views or a reset button.')
t('buttons', 'Add buttons with actions that navigate or apply a bookmark', 'Buttons turn a bookmark or page change into one click, which is how a report is made to feel like an application.')
t('tooltipcustom', 'Build a custom tooltip page', 'A tooltip page shows several related measures on hover, which adds context without cluttering the visual.')
t('reporttooltip', 'Set the tooltip to a report page and size it to the hover area', 'A report-page tooltip must be small enough to read on hover, and its filters must match the hovered data point.')
t('pageNav', 'Add a page navigator for the report', 'A page navigator generates navigation for every page automatically, which stays correct as pages are added.')
t('alttext', 'Provide alt text for each meaningful visual', 'Alt text describes the visual for a screen reader, which is required for an accessible report.')
t('taborder', 'Set a logical tab order for the interactive elements', 'Tab order decides the keyboard sequence, which is how a keyboard user reaches the controls in a sensible order.')
t('mobilelayout', 'Build the mobile layout in the mobile view', 'The mobile layout decides what a phone shows first, which is not the same as a squeezed desktop canvas.')
t('personalization', 'Enable personalization for the visuals the reader may change', 'Personalization lets a reader change visual type or fields without edit rights, while the author keeps the published default.')
t('exportsetting', 'Configure the export and download settings for the report', 'Export settings decide whether readers can take data out, which is a governance decision as much as a convenience.')
t('autorefresh', 'Configure automatic page refresh for the streaming tile', 'Automatic page refresh reloads a page on a timer, which suits an operational screen but must be limited to avoid query load.')
t('referenceline', 'Add a reference line for the target or average', 'A reference line gives the reader a comparison without a second visual, which turns a trend into a performance judgement.')
t('errorbars', 'Add error bars to show the uncertainty range', 'Error bars show the spread around a value, which stops a point estimate being read as certainty.')
t('forecast', 'Use the built-in forecast on a line chart', 'Forecasting extends the series statistically and shows a confidence band, which is only meaningful on a stable, seasonally understood series.')
t('grouping', 'Create groups for the categories that matter', 'Grouping combines members into meaningful buckets, which reduces clutter and matches how the business talks.')
t('binning', 'Create bins for a continuous measure', 'Binning turns a continuous value into ranges, which is how a distribution becomes readable.')
t('clustering', 'Use clustering to find segments in the data', 'Clustering groups similar rows statistically, which surfaces segments that were not defined in advance.')
t('outliers', 'Use the outlier detection feature on the visual', 'Outlier detection finds points that sit far from the pattern, which is often the first sign of a data or process problem.')
t('analyzefeature', 'Use the Analyze feature to explain a change', 'The Analyze feature decomposes a value into the dimensions that contribute most to the change, which answers why a number moved.')
t('keyinfluencers', 'Use the Key Influencers visual', 'Key Influencers ranks the factors associated with a metric, which is explanatory rather than causal.')
t('dextree', 'Use the Decomposition Tree visual', 'A decomposition tree lets the reader drill into any dimension in any order, which suits open-ended root-cause work.')
t('qnaFeature', 'Use Q&A to answer a natural-language question', 'Q&A maps a typed question to the model and returns a visual, which is fast for ad hoc questions if the model is well named.')
t('copilotnarrative', 'Use Copilot to create a narrative visual', 'A narrative visual summarizes the page in text, which helps a reader who wants the story rather than the chart.')
t('copilotpage', 'Use Copilot to suggest a report page', 'Copilot can draft a page from a prompt, which is a starting point that still needs an author to check the fields and layout.')

# --- Domain 4: workspaces, apps, refresh, security, governance ------------
t('workspace', 'Create a workspace for the team that owns the content', 'A workspace is the collaboration and permission boundary, so content shared by one team belongs in one workspace.')
t('wsadmin', 'Workspace Admin role', 'Admins manage the workspace, its members, and its settings, which is more than publishing content.')
t('wsmember', 'Workspace Member role', 'Members can publish and edit all content and add lower-privileged users, but cannot delete the workspace.')
t('wscontrib', 'Workspace Contributor role', 'Contributors can publish and edit content, which is the role for authors who should not manage membership.')
t('wsviewer', 'Workspace Viewer role', 'Viewers can read the content but not edit it, which is the safest role for consumers who work inside the workspace.')
t('appworkspace', 'Publish an app from the workspace', 'An app gives consumers a curated, read-only experience with its own audience list, instead of direct workspace access.')
t('appaudience', 'Define an app audience for each group of consumers', 'Audiences let one app show different content to different groups, which avoids maintaining several near-identical apps.')
t('appupdate', 'Update the app after changing the workspace content', 'Consumers see the published app, so workspace edits stay invisible until the app is updated.')
t('distribution', 'Choose the distribution method that matches the audience', 'App, shared link, Teams, or embedded all grant different levels of control, so the choice is a governance decision.')
t('dashboard', 'Create a dashboard in the service', 'A dashboard is a single-page canvas of pinned tiles from one or more reports, which suits monitoring rather than analysis.')
t('pinnedtile', 'Pin the visual to a dashboard tile', 'Pinning copies the visual to the dashboard, and the tile stays linked to the underlying report for drill-through.')
t('subscription', 'Create a subscription for the report or dashboard', 'A subscription delivers a snapshot on a schedule by email, which suits readers who will not open the report themselves.')
t('dataalert', 'Create a data alert on a dashboard tile', 'A data alert notifies when a single value crosses a threshold, and it only works on tiles, not on report visuals.')
t('tilealert', 'Set the alert threshold on the pinned card tile', 'Alerts are configured per tile value with a threshold and frequency, so the tile must expose the metric as a single number.')
t('gateway', 'Install an on-premises data gateway', 'A gateway provides the outbound connection from the service to an on-premises source, which cloud refresh requires.')
t('persgateway', 'Personal mode gateway', 'A personal gateway serves one author and cannot be shared, which makes it unsuitable for team-owned refresh.')
t('vnetgateway', 'Virtual network data gateway', 'A VNet gateway connects the service to sources inside an Azure virtual network without installing software on a server.')
t('schedrefresh', 'Configure scheduled refresh on the semantic model', 'Scheduled refresh controls how often the imported data is updated, which is the freshness guarantee the report can make.')
t('incrrefresh', 'Configure incremental refresh with the range parameters', 'Incremental refresh loads only new or changed partitions, which keeps refresh time and load predictable for a large fact table.')
t('paramsrefresh', 'Set the RangeStart and RangeEnd parameters the refresh policy expects', 'Incremental refresh requires the date parameters to filter the source query, or the policy has nothing to partition.')
t('credsrefresh', 'Update the credentials used by the refresh schedule', 'A scheduled refresh fails silently from the reader\'s point of view when the stored credential has expired.')
t('rlsrole', 'Define a row-level security role with a DAX filter', 'An RLS role filters the model per user at query time, which is how one report serves many regions without duplication.')
t('rlsdynamic', 'Use a dynamic RLS rule based on USERPRINCIPALNAME', 'A dynamic rule matches the signed-in user to a mapping table, which avoids maintaining one role per person.')
t('usernamefn', 'Map the signed-in user with USERPRINCIPALNAME in the filter', 'The filter compares the model column to the identity the service passes, which is the basis of dynamic security.')
t('viewas', 'Test the role with View as role in the service', 'View as role shows the report exactly as a member of the role sees it, which is how a security mistake is caught before release.')
t('rlsfixed', 'A static RLS role per region with fixed members', 'A static role is simple to reason about but must be maintained every time the org chart changes.')
t('rlsgroup', 'Add the security group to the role membership', 'Adding a group instead of individuals keeps role membership aligned with the directory and reduces drift.')
t('senslabel', 'Apply a sensitivity label to the semantic model and report', 'A sensitivity label travels with the exported file, which is how protection survives beyond the workspace.')
t('promoted', 'Promote the content as endorsed', 'Promotion signals the content is ready for reuse by the team, while certification asserts organization-wide trust.')
t('certified', 'Certify the semantic model', 'Certification requires a designated reviewer, which is how a single trusted model becomes the organization standard.')
t('itemaccess', 'Grant item-level access to the specific report', 'Item-level sharing grants one item without workspace membership, which limits what the recipient can discover.')
t('buildperm', 'Grant Build permission on the semantic model', 'Build lets another author create reports on the model without editing it, which is how reuse is enabled safely.')
t('lineage', 'Review lineage view', 'Lineage shows which reports depend on which model and source, which is how the impact of a change is scoped.')
t('impactanalysis', 'Run impact analysis before changing the model', 'Impact analysis lists the downstream items that will break, which prevents an unannounced outage for report consumers.')
t('usagemetrics', 'Review the usage metrics report', 'Usage metrics show which reports and pages are actually used, which is the evidence for retiring or investing in content.')
t('tenantsetting', 'Confirm the tenant setting allows the capability', 'A feature can be enabled for the tenant, a group, or nobody, so an unavailable option is often a tenant setting rather than a report setting.')

# --- Sequencing: 12 processes x 4 variants ---------------------------------
t('seqprofok', 'Profile the source → fix types and nulls → shape the table → load only the needed columns', 'Profiling first prevents wasted shaping, and typing before loading keeps the model small and time intelligence working.')
t('seqprofbad1', 'Load the table → discover the type errors in the report → re-import the source', 'Discovering type errors after load means the model was built on wrong data and the work restarts.')
t('seqprofbad2', 'Shape the table → delete the profiling steps → load every column', 'Deleting profiling removes the evidence of quality problems and loading every column inflates the model.')
t('seqprofbad3', 'Load every column → profile in the report → patch the visual', 'Patching visuals hides the data problem instead of fixing it at the source.')
t('seqcleanok', 'Identify the bad values → standardize text → convert types → document what was replaced', 'Cleaning in that order fixes the cause, and documenting the replacement keeps the change auditable.')
t('seqcleanbad1', 'Replace all values with a default → convert types → load', 'Replacing everything with a default destroys real values and hides the pattern behind the error.')
t('seqcleanbad2', 'Convert types first → then look for duplicates → then trim', 'Converting before trimming fails on values that only differ by whitespace and leaves duplicates behind.')
t('seqcleanbad3', 'Filter out the failing rows → load → ask the business later', 'Silently dropping rows changes the totals and the business never learns what is missing.')
t('seqmergeok', 'Check the key uniqueness → merge or append → expand the needed columns → validate the row count', 'Validating the key before the merge prevents a fan-out, and a row-count check catches a join that multiplied rows.')
t('seqmergebad1', 'Merge the tables → expand every column → load → check totals in the report', 'Expanding every column adds unused data and finding the problem in the report is too late to protect the totals.')
t('seqmergebad2', 'Append the two tables → assume the keys match → load', 'Append stacks rows and does not match keys, so a key mismatch becomes a silent duplication.')
t('seqmergebad3', 'Duplicate the query for each table → merge the duplicates → delete the original', 'Duplicating then merging the copies leaves two step chains to maintain and no single source of truth.')
t('seqstarok', 'Define the grain → separate facts from dimensions → add surrogate keys → relate dimension to fact', 'The grain decides what a row means, and separating descriptive attributes is what makes a star schema work.')
t('seqstarbad1', 'Keep one wide table → relate it to itself → build measures', 'A single wide table cannot be filtered cleanly by dimension and pushes duplication into every row.')
t('seqstarbad2', 'Create a dimension per column → relate each one to the fact', 'A dimension per column produces a hub of one-column tables and makes the model unmaintainable.')
t('seqstarbad3', 'Build the relationships first → decide the grain afterwards → load', 'Relationships built before the grain is agreed will be wrong and must be rebuilt.')
t('seqdateok', 'Create a contiguous date table → mark it as the date table → relate it to the fact dates → build time intelligence on it', 'Time intelligence needs a marked, contiguous table, and relating it properly is what makes the measures respond to slicers.')
t('seqdatebad1', 'Use the fact date column directly → write TOTALYTD → add a date slicer', 'A fact date column has gaps, so year-to-date silently skips missing days and the slicer shows no clean hierarchy.')
t('seqdatebad2', 'Create a date table → leave it unrelated → filter with it', 'An unrelated date table filters nothing, so the slicer appears to work while the visuals ignore it.')
t('seqdatebad3', 'Create one date table per date column → relate all of them to the fact', 'Several date tables multiply relationships and make every time measure ambiguous.')
t('seqrlsok', 'Model the mapping table → create the role with the DAX filter → add groups to the role → test with View as role', 'Testing with View as role is the only way to confirm what a member actually sees before release.')
t('seqrlsbad1', 'Create the role → publish → ask the business to confirm the filter', 'Asking the business to confirm security without testing the role means the first failure is a real disclosure.')
t('seqrlsbad2', 'Filter the report visual → publish → assume the model is secured', 'A visual-level filter is not security, because anyone with Build permission can bypass it.')
t('seqrlsbad3', 'Create one role per user → never review membership → publish the app', 'One role per person drifts out of date immediately and cannot be audited at scale.')
t('seqrefreshok', 'Confirm the gateway or cloud connection → store credentials → set the schedule → check refresh history', 'Refresh depends on connectivity and credentials before the schedule matters, and history is how a failure is detected.')
t('seqrefreshbad1', 'Set the schedule → publish → wait for the first failure email', 'Scheduling before connectivity and credentials are proven guarantees a failed first refresh.')
t('seqrefreshbad2', 'Use a personal gateway → schedule → leave the team to maintain it', 'A personal gateway fails when the individual is unavailable or changes machines.')
t('seqrefreshbad3', 'Increase the refresh frequency to hourly → ignore the source load', 'Refreshing hourly without checking source capacity overloads the source and can exceed the refresh window.')
t('seqincrok', 'Add RangeStart and RangeEnd parameters → filter the source query → configure the refresh policy → publish and refresh', 'Incremental refresh only partitions the query when the parameters filter it, and the policy must exist in the published model.')
t('seqincrbad1', 'Configure the policy in Desktop → publish → assume partitions were created', 'The policy is applied when the model is published and refreshed, so assuming it worked leaves a full load in place.')
t('seqincrbad2', 'Filter the query by date → set the policy → skip the parameters', 'A policy without the parameter filter has nothing to partition and falls back to loading everything.')
t('seqincrbad3', 'Load all history every refresh → add a policy later → hope it rebuilds', 'A later policy does not rewrite history that was never partitioned, so the load stays slow.')
t('seqdeployok', 'Build in a development workspace → validate in test → promote through the pipeline to production', 'Promoting the same item through stages keeps the definition identical and puts validation before release.')
t('seqdeploybad1', 'Edit directly in production → copy the file as a backup → publish over it', 'Editing in production exposes consumers to unfinished work and a copied file is not a controlled version.')
t('seqdeploybad2', 'Publish from Desktop to every workspace separately → reconcile by hand', 'Separate publishes drift apart immediately, and reconciling by hand is where definitions diverge.')
t('seqdeploybad3', 'Create a second report for each environment → maintain them in parallel', 'Parallel copies double the maintenance and the definitions eventually disagree.')
t('seqappok', 'Build in the workspace → curate the app pages → assign audiences → publish and update the app', 'Audiences control who sees what, and consumers only see changes when the app is updated.')
t('seqappbad1', 'Give every consumer the workspace Viewer role → skip the app', 'Direct workspace access exposes everything in the workspace and cannot be curated per audience.')
t('seqappbad2', 'Publish the app before the report is finished → update it never', 'Publishing an unfinished report sets expectations you cannot meet and consumers see the version you last shipped.')
t('seqappbad3', 'Create one app per person → assign each audience manually', 'An app per person is unmaintainable and defeats the point of audiences.')
t('seqbookmarkok', 'Create the views → capture each in a bookmark → add buttons → hide the visuals not in use', 'Bookmarks store state and buttons apply it, which is what makes a single page behave like several.')
t('seqbookmarkbad1', 'Create a page per view → duplicate the visuals → maintain each page', 'Duplicating pages multiplies maintenance and the copies drift apart.')
t('seqbookmarkbad2', 'Capture a bookmark before setting the filters → expect it to restore them', 'A bookmark captures the state at the moment it is created, so filters set afterwards are not stored.')
t('seqbookmarkbad3', 'Use buttons without actions → tell readers to click twice', 'A button with no action is decoration and the report still has no navigation.')
t('seqperfok', 'Measure with Performance Analyzer → isolate the slow measure or visual → reduce columns or granularity → re-measure', 'Measuring first targets the real cost, and re-measuring proves the change helped instead of assuming it.')
t('seqperfbad1', 'Delete visuals until the page loads → call it optimization', 'Removing content reduces value without addressing the underlying query cost.')
t('seqperfbad2', 'Rewrite every measure as a calculated column → reload', 'Calculated columns are stored per row and usually make the model larger and slower.')
t('seqperfbad3', 'Buy more capacity → skip the model review', 'Capacity masks an inefficient model and the cost recurs as data grows.')
t('seqgovok', 'Inventory the content → assign owners and endorsement → apply sensitivity labels → review usage', 'Ownership and labels make the estate manageable, and usage review is what retires content that nobody reads.')
t('seqgovbad1', 'Publish everything to one workspace → give all staff Contributor', 'A shared workspace with broad Contributor rights removes the audit trail and lets anyone change production content.')
t('seqgovbad2', 'Label the reports only → leave the models unlabelled', 'A model without a label exports unprotected data even when its reports are labelled.')
t('seqgovbad3', 'Retire nothing → add new content beside the old', 'Unretired content accumulates, and readers cannot tell which report is current.')

t('seqdrillok', 'Choose the entity field → create the drillthrough page → place the entity filter → add a back button', 'The drillthrough filter is what carries the selection, and the back button is what keeps the reader oriented.')
t('seqdrillbad1', 'Create the detail page → add a visual → tell readers to filter it manually', 'A page without the drillthrough filter does not carry the selected entity, so the detail is not about what was clicked.')
t('seqdrillbad2', 'Set the drillthrough filter → publish → skip the back button', 'Without a back button the reader is stranded on the detail page and loses the summary context.')
t('seqdrillbad3', 'Put every field on the summary visual → expect drillthrough to work', 'Too many fields on one visual makes the click target ambiguous and the drill result unpredictable.')
